// Des: CLI glue for the local browser: session, actions, login command
// Flo: expand profile dir (+ account name) > Rndr or none > read steps file under the step cap > login = headed Chrome until the owner closes it
// I/O: Ctx (caller) > Rndr / Acts; login prints one status line; owner types credentials by hand, scra never sees them
// ===================================================================
const std = @import("std"); const cx = @import("ct-ctrl-ctxz.zig"); const rend = @import("nt-brow-rend.zig"); const actz = @import("nt-brow-acts.zig"); const chro = @import("nt-brow-chro.zig"); const pexp = @import("ut-path-expa.zig"); const acct = @import("ru-acct-guar.zig"); const pipe = @import("ru-page-fetc.zig");
fn nameOk(txt: []const u8) bool { if (txt.len == 0 or txt.len > 32) return false; for (txt) |chr| { if (!std.ascii.isAlphanumeric(chr) and chr != '-' and chr != '_') return false; } return true; }
pub fn profDir(ctx: *const cx.Ctx, name: []const u8) ![]const u8 { const base = pexp.pathExpa(ctx.allo, ctx.home, ctx.conf.brow_prof_dirz) catch return error.BadConfig; if (name.len == 0) return base; if (!nameOk(name)) return error.BadUsage; return std.fs.path.join(ctx.allo, &.{ base, name }); }
pub fn brwMake(ctx: *const cx.Ctx, name: []const u8) !?rend.Rndr { if (!ctx.conf.brow_enab) return null; return try rend.rndrInit(ctx.init.gpa, ctx.iozz, ctx.conf, try profDir(ctx, name)); }
pub fn actsOf(ctx: *const cx.Ctx) !actz.Acts { var acts: actz.Acts = .{ .scrl = ctx.args.scrl, .clic = ctx.args.clic, .cons = ctx.args.cons }; if (ctx.args.steps.len > 0) { const txt = std.Io.Dir.cwd().readFileAlloc(ctx.iozz, ctx.args.steps, ctx.allo, .limited(1 << 20)) catch return error.BadUsage; acts.steps = try actz.stepsRead(ctx.allo, txt, ctx.conf.brow_step_maxz); } return acts; }
pub fn runLogin(ctx: *const cx.Ctx) !u8 { const name = ctx.args.urlz; if (!ctx.conf.logi_mode_enab or !ctx.conf.brow_enab) return error.NotConfigured; if (!nameOk(name)) return error.BadUsage; const exe = (try chro.exeFind(ctx.init.gpa, ctx.iozz, ctx.conf.brow_path_exec)) orelse return error.NoBrowser; defer ctx.init.gpa.free(exe); const prof = try profDir(ctx, name); var brw = try chro.launch(ctx.init.gpa, ctx.iozz, exe, prof, false, 30000); try cx.outz(ctx, try std.fmt.allocPrint(ctx.allo, "login '{s}': a browser window is open. Log in by hand, then close the window. scra never sees what you type.", .{name})); while (!chro.portDead(ctx.init.gpa, ctx.iozz, brw.port)) std.Io.sleep(ctx.iozz, .fromMilliseconds(1000), .awake) catch {}; brw.stop(); var dbzz = try cx.dbOpen(ctx); defer dbzz.close(); try acct.acctClear(&dbzz, name); try cx.outz(ctx, try std.fmt.allocPrint(ctx.allo, "login '{s}': session saved. Use: scra fetch <url> --live --account {s}", .{ name, name })); _ = pipe.nowMs; return 0; }
